function avisarEleccion(e){try{navigator.sendBeacon&&navigator.sendBeacon("/api/privacidad?e="+e)}catch(x){}}function esPrimeraPagina(){try{return!document.referrer||new URL(document.referrer).host!==location.host}catch(x){return true}}document.addEventListener("DOMContentLoaded",function(){if(!getCookie("cookiesAceptadas")){document.getElementById("cookieConsent").style.display="block";if(esPrimeraPagina())avisarEleccion("mostrado")}});function setCookie(name,value,days){let expires="";if(days){const date=new Date;date.setTime(date.getTime()+days*24*60*60*1e3);expires="; expires="+date.toUTCString()}document.cookie=name+"="+(value||"")+expires+"; path=/"}function getCookie(name){const nameEQ=name+"=";const ca=document.cookie.split(";");for(let i=0;i<ca.length;i++){let c=ca[i];while(c.charAt(0)==" ")c=c.substring(1,c.length);if(c.indexOf(nameEQ)==0)return c.substring(nameEQ.length,c.length)}return null}function actualizarConsentimiento(estado){if(typeof gtag==="function"){gtag("consent","update",{ad_storage:estado,ad_user_data:estado,ad_personalization:estado,analytics_storage:estado})}}function aceptarCookies(){avisarEleccion("aceptar");setCookie("cookiesAceptadas","true",365);actualizarConsentimiento("granted");document.getElementById("cookieConsent").style.display="none"}function rechazarCookies(){avisarEleccion("rechazar");setCookie("cookiesAceptadas","false",365);actualizarConsentimiento("denied");document.getElementById("cookieConsent").style.display="none"}function configurarCookies(){window.location.href="/politica-cookies.html#configuracion"}